def optimal_stone_game_difference(stones):
    prefix = []
    running = 0
    for value in stones:
        running += value
        prefix.append(running)
    best = prefix[-1]
    for index in range(len(stones) - 2, 0, -1):
        best = max(best, prefix[index] - best)
    return best

